"use client";

import { startTransition, type FormEvent } from "react";

/**
 * React 19 resets uncontrolled form fields after a form action completes — even when the server
 * returned validation errors. Submitting through this handler keeps what the user typed.
 * The form's `action` attribute is still set, so it works without JavaScript too.
 */
export function keepFormOnSubmit(dispatch: (fd: FormData) => void) {
  return (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const fd = new FormData(e.currentTarget, (e.nativeEvent as SubmitEvent).submitter);
    startTransition(() => dispatch(fd));
  };
}
